<?php namespace App\Http\Controllers; use App\Enums\OrderStatus; use App\Models\Order; use Illuminate\Http\Request; class PayFastController extends Controller { public function notify(Request $r){$order=Order::whereNumber($r->input('m_payment_id'))->firstOrFail();if($r->input('payment_status')==='COMPLETE'&&(float)$r->input('amount_gross')===(float)$order->grand_total){$order->update(['status'=>OrderStatus::Paid]);$order->payment()->update(['status'=>'paid','gateway_reference'=>$r->input('pf_payment_id'),'payload'=>$r->all(),'paid_at'=>now()]);}return response('OK');} public function returned(string $order){return view('storefront.payment-return',['order'=>Order::whereNumber($order)->firstOrFail()]);} public function cancelled(string $order){return view('storefront.payment-cancel',['order'=>$order]);} }
